const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
  const modalRef = useRef(null);
  const triggerRef = useRef(null);

  // Focus management
  useEffect(() => {
    if (isOpen) {
      // Save trigger element to return focus later
      triggerRef.current = document.activeElement;

      // Move focus into the modal
      // We'll focus the first focusable element or the modal itself
      const focusableElements = modalRef.current.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      );
      if (focusableElements.length > 0) {
        focusableElements[0].focus();
      }

      // Add escape key listener
      const handleKeyDown = (e) => {
        if (e.key === 'Escape') {
          onClose();
        }

        // Focus trap
        if (e.key === 'Tab') {
          const focusable = modalRef.current.querySelectorAll(
            'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
          );
          const first = focusable[0];
          const last = focusable[focusable.length - 1];

          if (e.shiftKey) {
            if (document.activeElement === first) {
              last.focus();
              e.preventDefault();
            }
          } else {
            if (document.activeElement === last) {
              first.focus();
              e.preventDefault();
            }
          }
        }
      };

      document.addEventListener('keydown', handleKeyDown);

      // Prevent scrolling on body
      document.body.style.overflow = 'hidden';

      return () => {
        document.removeEventListener('keydown', handleKeyDown);
        document.body.style.overflow = 'unset';
        // Return focus to trigger
        if (triggerRef.current) {
          triggerRef.current.focus();
        }
      };
    }
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return ReactDOM.createPortal(
    <div className="modal-overlay" onClick={onClose}>
      <div 
        className="modal-content" 
        ref={modalRef}
        role="dialog" 
        aria-modal="true" 
        aria-labelledby="modal-title"
        aria-describedby="modal-desc"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-header">
          <h2 id="modal-title">{title}</h2>
        </div>
        <div className="modal-body">
          <p id="modal-desc">{children}</p>
        </div>
        <div className="modal-footer">
          <button className="btn-secondary" onClick={onClose}>
            Cancel
          </button>
          <button className="btn-danger" onClick={onConfirm}>
            Delete
          </button>
        </div>
      </div>
    </div>,
    document.body
  );
};

const ImagePreview = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleDeleteClick = () => {
    setIsModalOpen(true);
  };

  const handleConfirmDelete = () => {
    alert("Image deleted (simulated)");
    setIsModalOpen(false);
  };

  return (
    <div className="container">
      <header>
        <h1>Image Library</h1>
      </header>
      <main>
        <div className="image-card">
          <div className="image-wrapper">
            <img 
              src="https://images.unsplash.com/photo-1511300636408-a63a89df3482?auto=format&fit=crop&q=80&w=800" 
              alt="Mountain landscape during sunset with dark clouds" 
            />
          </div>
          <div className="image-details">
            <div className="image-info">
              <h2>Dark Peaks</h2>
              <p>Uploaded May 6, 2026</p>
            </div>
            <button className="trigger" onClick={handleDeleteClick}>
              Delete Image
            </button>
          </div>
        </div>
      </main>

      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)}
        onConfirm={handleConfirmDelete}
        title="Confirm Deletion"
      >
        Are you sure you want to delete "Dark Peaks"? This action cannot be undone.
      </Modal>
    </div>
  );
};

const App = () => {
  return <ImagePreview />;
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
